-- Demo database for the sqltest fixtures (Firebird 3). Invented placeholder data.
CREATE DOMAIN d_preis AS NUMERIC(8,2) CHECK (VALUE >= 0);

CREATE TABLE artikel (
    artikel_id  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kuerzel     CHAR(6)      NOT NULL UNIQUE,
    bezeichnung VARCHAR(40)  NOT NULL,
    preis       d_preis      NOT NULL,
    angelegt    DATE         NOT NULL
);
